param([Parameter(Mandatory=$true)][string]$MigrationPath,[switch]$VerifyLive,[switch]$VerifyNativeCatalog)
$ErrorActionPreference='Stop';$repo=[IO.Path]::GetFullPath("$PSScriptRoot/../..");$out="$repo/build-extractors/runtime-test/kingslayers-return-data"
& "$PSScriptRoot/Invoke-WithRuntimeDiagnostics.ps1" -EvidenceDirectory $out -RuntimeDirectories @($out,"$repo/build-extractors/runtime-test/legion-legendary-catalog") -Test {
 $migration=[IO.File]::ReadAllText((Resolve-Path $MigrationPath))
 $db=(Get-Content "$repo/build-extractors/bin/Release/worldserver.conf"|Where-Object {$_ -match '^WorldDatabaseInfo\s*='}).Split('"')[1].Split(';');$number=0
 function Query([string]$sql,[switch]$Refusal){$script:number++;$stderr="$out/stderr-$script:number.txt";$prior=$env:MYSQL_PWD;$old=$ErrorActionPreference;try{$env:MYSQL_PWD=$db[3];$ErrorActionPreference='Continue';$rows=@($sql|& C:/wamp64/bin/mariadb/mariadb11.4.9/bin/mysql.exe --host=$($db[0]) --port=$($db[1]) --user=$($db[2]) --database=$($db[4]) --batch --raw --skip-column-names 2> $stderr);$code=$LASTEXITCODE}finally{$env:MYSQL_PWD=$prior;$ErrorActionPreference=$old};if($Refusal){if(!$code -or (Get-Content $stderr -Raw) -notmatch 'Kingslayers return custom source/binding differs'){throw 'Expected Kingslayers custom-source refusal absent'};'PASS expected custom-source refusal'}else{if($code -or (Get-Item $stderr).Length){Get-Content $stderr;throw 'Kingslayers return SQL failed'};if($rows -match '^FAIL'){throw 'Kingslayers return data mismatch'};$rows}}
 $filters=[ordered]@{gameobject_template='entry IN(251123,251107)';gameobject='id=251123';spell_script_names='spell_id=215151';event_scripts='id=51617';gameobject_scripts='id=134046';smart_scripts='source_type=1 AND entryorguid IN(251123,-134046)';spell_target_position='id=215151'}
 $setup='';foreach($t in $filters.Keys){$setup+="CREATE TEMPORARY TABLE saved_$t LIKE $t;INSERT INTO saved_$t SELECT * FROM $t WHERE $($filters[$t]);CREATE TEMPORARY TABLE $t LIKE saved_$t;INSERT INTO $t SELECT * FROM saved_$t;"}
 $setup+="UPDATE gameobject_template SET ScriptName='' WHERE entry=251123 AND ScriptName='go_kingslayers_return';DELETE FROM spell_script_names WHERE spell_id=215151 AND ScriptName='spell_kingslayers_return';"
 $check="SELECT IF((SELECT COUNT(*) FROM gameobject_template WHERE entry=251123 AND ScriptName='go_kingslayers_return' AND Data10=215151 AND flags=32)=1 AND (SELECT COUNT(*) FROM spell_script_names WHERE spell_id=215151 AND ScriptName='spell_kingslayers_return')=1,'PASS native portal/bindings','FAIL portal binding');"
 # Compare complete template/spawn rows, allowing precisely the new ScriptName.
 $check+="UPDATE gameobject_template SET ScriptName='' WHERE entry=251123;SELECT IF(NOT EXISTS(SELECT * FROM gameobject_template EXCEPT SELECT * FROM saved_gameobject_template) AND NOT EXISTS(SELECT * FROM saved_gameobject_template EXCEPT SELECT * FROM gameobject_template),'PASS complete original template retention','FAIL template retention');UPDATE gameobject_template SET ScriptName='go_kingslayers_return' WHERE entry=251123;SELECT IF(NOT EXISTS(SELECT * FROM gameobject EXCEPT SELECT * FROM saved_gameobject) AND NOT EXISTS(SELECT * FROM saved_gameobject EXCEPT SELECT * FROM gameobject),'PASS full native spawn retention','FAIL spawn retention');"
 # Normalize only the saved applied binding for repeatable comparison after deployment.
 $setup+="UPDATE saved_gameobject_template SET ScriptName='' WHERE entry=251123 AND ScriptName='go_kingslayers_return';"
 Query ($setup+$migration+$check+$migration+$check)
 $changes=@("UPDATE gameobject_template SET Data10=1 WHERE entry=251123;","UPDATE gameobject_template SET ScriptName='custom' WHERE entry=251123;","UPDATE gameobject_template SET AIName='SmartGameObjectAI' WHERE entry=251123;","UPDATE gameobject_template SET flags=0 WHERE entry=251123;","UPDATE gameobject SET phaseMask=2 WHERE guid=134046;","UPDATE gameobject SET map=1 WHERE guid=134046;","INSERT INTO spell_script_names VALUES(215151,'custom');","INSERT INTO event_scripts(id) VALUES(51617);","INSERT INTO gameobject_scripts(id) VALUES(134046);","INSERT INTO smart_scripts(entryorguid,source_type,id,comment) VALUES(251123,1,0,'custom');")
 $changes+=@("UPDATE spell_target_position SET target_map=1 WHERE id=215151;","DELETE FROM spell_target_position WHERE id=215151;")
 foreach($applied in @($false,$true)){foreach($change in $changes){Query ($setup+$(if($applied){$migration}else{''})+$change+$migration) -Refusal}}
 Query "SET SESSION TRANSACTION READ ONLY;SELECT IF((SELECT COUNT(*) FROM spell_target_position WHERE id=215151 AND target_map=1220 AND ABS(target_position_x+854.53)<0.01 AND ABS(target_position_y-4597.28)<0.01 AND ABS(target_position_z-748.81)<0.01)=1,'PASS unchanged native teleport destination','FAIL native destination');"
 if($VerifyLive){$hash=[BitConverter]::ToString([Security.Cryptography.SHA1]::Create().ComputeHash([Text.Encoding]::UTF8.GetBytes($migration.Replace("`r`n","`n")))).Replace('-','');Query "SET SESSION TRANSACTION READ ONLY;SELECT IF((SELECT COUNT(*) FROM updates WHERE name='2026_10_27_18_kingslayers_accepted_return.sql' AND hash='$hash' AND state='RELEASED')=1 AND (SELECT COUNT(*) FROM gameobject_template WHERE entry=251123 AND ScriptName='go_kingslayers_return')=1 AND (SELECT COUNT(*) FROM spell_script_names WHERE spell_id=215151 AND ScriptName='spell_kingslayers_return')=1,'PASS live updater/hash/bindings','FAIL live updater');"}
 if($VerifyNativeCatalog){$previous=$env:LEGION_DIALOGUE_CONFIG;try{$env:LEGION_DIALOGUE_CONFIG="$repo/build-extractors/bin/Release/worldserver.conf";& "$repo/tools/research/Read-LegionLegendaryCatalog.ps1" -SourceFile KingslayersPickupCatalog.cpp -ProbeName KingslayersPickupCatalog -OutputFile "$out/native.tsv"}finally{$env:LEGION_DIALOGUE_CONFIG=$previous};$rows=Get-Content "$out/native.tsv";foreach($expected in @("EFFECT`t215151`t0`t61`t0`t51617`t0`t0`t0","EFFECT`t215151`t1`t252`t0`t0`t0`t1`t17","MISC`t215151`t0`t1`t0`t0","TREE`t48593`t48592`t1`t30477`t92`t51617","TREE`t48529`t48528`t1`t30445`t152`t1123","TREE`t48549`t48548`t1`t30454`t152`t1123","STEP_REWARD`t9`t0")){if($rows -notcontains $expected){throw "Native return contract differs: $expected"}};'PASS native26972 targetless event, instant self/DB teleport, both quest scenario roots and actual final criterion/no auto reward'}
}
